439	/*
440	 * calculate groupdelay
441	 */
442	static float
443	groupdelay(const float *v, const float *w, float deltaf)
444	{
445	#if 1
446	  // atan(w)-atan(v) = atan((w-v)/(1+wv))
447	  float r = w[0]*v[1] - w[1]*v[0];
448	  float i = w[0]*v[0] + w[1]*v[1];
449	  return atan2f(r, i) / (2 * VNA_PI * deltaf);
450	#else
451	  return (atan2f(w[0], w[1]) - atan2f(v[0], v[1])) / (2 * VNA_PI * deltaf);
452	#endif
453	}
