502	static void
503	cartesian_scale(float re, float im, int *xp, int *yp, float scale)
504	{
505	  //float scale = 4e-3;
506	  int x = float2int(re * P_RADIUS * scale);
507	  int y = float2int(im * P_RADIUS * scale);
508	  if      (x < -P_RADIUS) x = -P_RADIUS;
509	  else if (x >  P_RADIUS) x =  P_RADIUS;
510	  if      (y < -P_RADIUS) y = -P_RADIUS;
511	  else if (y >  P_RADIUS) y =  P_RADIUS;
512	  *xp = P_CENTER_X + x;
513	  *yp = P_CENTER_Y - y;
514	}
