525	static float
526	gamma2resistance(const float v[2])
527	{
528	  float z0 = 50;
529	  float d = z0 / ((1-v[0])*(1-v[0])+v[1]*v[1]);
530	  return ((1+v[0])*(1-v[0]) - v[1]*v[1]) * d;
531	}
