541	static index_t
542	trace_into_index(int t, int i, float array[POINTS_COUNT][2])
543	{
544	  int y, x;
545	
546	  float *coeff = array[i];
547	  float refpos = NGRIDY - get_trace_refpos(t);
548	  float v = refpos;
549	  float scale = 1 / get_trace_scale(t);
550	  switch (trace[t].type) {
551	  case TRC_LOGMAG:
552	    v-= logmag(coeff) * scale;
553	    break;
554	  case TRC_PHASE:
555	    v-= phase(coeff) * scale;
556	    break;
557	  case TRC_DELAY:
558	    v-= groupdelay_from_array(i, array) * scale;
559	    break;
560	  case TRC_LINEAR:
561	    v+= linear(coeff) * scale;
562	    break;
563	  case TRC_SWR:
564	    v+= (1 - swr(coeff)) * scale;
565	    break;
566	  case TRC_REAL:
567	    v-= coeff[0] * scale;
568	    break;
569	  case TRC_IMAG:
570	    v-= coeff[1] * scale;
571	    break;
572	  case TRC_R:
573	    v-= resitance(coeff) * scale;
574	    break;
575	  case TRC_X:
576	    v-= reactance(coeff) * scale;
577	    break;
578	  case TRC_Q:
579	    v-= qualityfactor(coeff) * scale;
580	    break;
581	  case TRC_SMITH:
582	  //case TRC_ADMIT:
583	  case TRC_POLAR:
584	    cartesian_scale(coeff[0], coeff[1], &x, &y, scale);
585	    goto set_index;
586	  }
587	  if (v <  0) v = 0;
588	  if (v > NGRIDY) v = NGRIDY;
589	  x = (i * (WIDTH) + (sweep_points-1)/2) / (sweep_points-1) + CELLOFFSETX;
590	  y = float2int(v * GRIDY);
591	set_index:
592	  return INDEX(x, y);
593	}
