870	//
871	// in most cases _compute_outcode clip calculation not give render line speedup
872	//
873	static inline void
874	cell_drawline(int x0, int y0, int x1, int y1, int c)
875	{
876	  if (x0 < 0 && x1 < 0) return;
877	  if (y0 < 0 && y1 < 0) return;
878	  if (x0 >= CELLWIDTH && x1 >= CELLWIDTH) return;
879	  if (y0 >= CELLHEIGHT && y1 >= CELLHEIGHT) return;
880	
881	  // modifed Bresenham's line algorithm, see https://en.wikipedia.org/wiki/Bresenham%27s_line_algorithm
882	  if (x1 < x0) { SWAP(x0, x1); SWAP(y0, y1); }
883	  int dx = x1 - x0;
884	  int dy = y1 - y0, sy = 1; if (dy < 0) { dy = -dy; sy = -1; }
885	  int err = (dx > dy ? dx : -dy) / 2;
886	
887	  while (1) {
888	    if (y0 >= 0 && y0 < CELLHEIGHT && x0 >= 0 && x0 < CELLWIDTH)
889	      cell_buffer[y0 * CELLWIDTH + x0] |= c;
890	    if (x0 == x1 && y0 == y1)
891	      return;
892	    int e2 = err;
893	    if (e2 > -dx) { err -= dy; x0++;  }
894	    if (e2 <  dy) { err += dx; y0+=sy;}
895	  }
896	}
