1169	search_nearest_index(int x, int y, int t)
1170	{
1171	  index_t *index = trace_index[t];
1172	  int min_i = -1;
1173	  int min_d = 1000;
1174	  int i;
1175	  for (i = 0; i < sweep_points; i++) {
1176	    int16_t dx = x - CELL_X(index[i]);
1177	    int16_t dy = y - CELL_Y(index[i]);
1178	    if (dx < 0) dx = -dx;
1179	    if (dy < 0) dy = -dy;
1180	    if (dx > 20 || dy > 20)
1181	      continue;
1182	    int d = dx*dx + dy*dy;
1183	    if (d < min_d) {
1184	      min_d = d;
1185	      min_i = i;
1186	    }
1187	  }
1188	  return min_i;
1189	}
